import{_ as o,o as e,c as a,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const q=JSON.parse('{"title":"学习笔记 · 心得记录","description":"","frontmatter":{},"headers":[],"relativePath":"notes/index.md","filePath":"notes/README.md","lastUpdated":1788475713000}'),d={name:"notes/index.md"};function r(i,t,l,n,c,u){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="学习笔记-·-心得记录" tabindex="-1">学习笔记 · 心得记录 <a class="header-anchor" href="#学习笔记-·-心得记录" aria-label="Permalink to &quot;学习笔记 · 心得记录&quot;">​</a></h1><blockquote><p>随读随记：<strong>在正文任意位置用鼠标选中文字</strong>，就会出现&quot;📝 记笔记&quot;工具条；笔记锚定到选中文本，刷新页面后自动重新高亮。数据默认只存在<strong>你的浏览器 localStorage</strong>（不注册、无账号、无数据库、别人看不到）；需要沉淀时一键导出为 GitHub Issue，或复制 Markdown 粘贴到 Discussions / 任意笔记软件。</p></blockquote><h2 id="这个工具能做什么" tabindex="-1">这个工具能做什么 <a class="header-anchor" href="#这个工具能做什么" aria-label="Permalink to &quot;这个工具能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作</th><th>说明</th></tr></thead><tbody><tr><td>划词记笔记</td><td>选中正文文字 → 点工具条&quot;记笔记&quot;→ 写下心得保存；选中处立即高亮</td></tr><tr><td>查看 / 编辑</td><td>点高亮文字可编辑该条笔记；右下角 📝 面板可看&quot;本页 / 全部&quot;</td></tr><tr><td>复制 Markdown</td><td>一键复制带页面来源和划词引用的 Markdown，可粘贴到 GitHub Discussions</td></tr><tr><td>导出 Issue</td><td>预填 <code>issues/new?title=…&amp;body=…</code>，登录 GitHub 后确认即发布，无需 token</td></tr><tr><td>删除</td><td>单条删除（有确认），对应高亮一并移除；不提供&quot;清空&quot;，防误删</td></tr></tbody></table><h2 id="高亮是怎么实现的" tabindex="-1">高亮是怎么实现的 <a class="header-anchor" href="#高亮是怎么实现的" aria-label="Permalink to &quot;高亮是怎么实现的&quot;">​</a></h2><p>笔记保存时记录选中文字在正文 <code>#content</code> 里的<strong>字符起止偏移</strong>，刷新页面后按偏移重新包裹 <code>&lt;mark&gt;</code>。局限：</p><ul><li>偏移基于当前页面文本；如果这本书的内容后来被修改（比如某章重写），旧笔记的偏移可能错位或不再高亮，但笔记内容和原文都还在面板里，复制/导出不受影响；</li><li>跨多个连续段落的选择会按文本节点分段高亮，显示为一段连续的黄色底纹。</li></ul><h2 id="数据存在哪" tabindex="-1">数据存在哪 <a class="header-anchor" href="#数据存在哪" aria-label="Permalink to &quot;数据存在哪&quot;">​</a></h2><ul><li><strong>localStorage</strong>：键为 <code>cs-notes:v1:&lt;页面路径&gt;</code>，只在你当前浏览器。换设备、清缓存、开无痕即不可见——它是&quot;草稿区&quot;，不是存档。</li><li><strong>GitHub Issues</strong>：导出后存在仓库 Issues 里，可搜索、打标签、转 PR，随仓库一起版本化。</li><li><strong>GitHub Discussions</strong>：GitHub 没有&quot;预填新建讨论&quot;的链接，所以这里用&quot;复制 Markdown&quot;代替——粘贴发布即可；若想&quot;一键发 Discussion&quot;，后续可以注册免费 OAuth App 走 GraphQL API（本工具暂不内置）。</li></ul><h2 id="把笔记变成正式章节" tabindex="-1">把笔记变成正式章节 <a class="header-anchor" href="#把笔记变成正式章节" aria-label="Permalink to &quot;把笔记变成正式章节&quot;">​</a></h2><p>笔记面板里的内容只是草稿。想让它成为这本书的一部分（被搜索、随 GitHub Actions 部署、保留版本历史）：</p><ol><li>把内容整理成 Markdown，追加到对应部分的章节文件，或新建文件；</li><li>挂进 <a href="./../SUMMARY">SUMMARY.md</a>；</li><li><code>commit + push</code>，Actions 自动构建部署到 GitHub Pages。</li></ol><h2 id="实现与配置" tabindex="-1">实现与配置 <a class="header-anchor" href="#实现与配置" aria-label="Permalink to &quot;实现与配置&quot;">​</a></h2><ul><li>组件：<code>.vitepress/theme/notes.ts</code>（无框架依赖的原生 DOM 逻辑，样式在 <code>notes.css</code>）。</li><li>挂载：VitePress 主题扩展（<code>Layout</code> 的 <code>layout-bottom</code> 插槽，见 <code>.vitepress/theme/index.ts</code>），SPA 路由切换后自动重建高亮。</li><li>目标仓库：<code>notes.ts</code> 顶部的 <code>GITHUB_REPO</code> 常量，导出 Issue 时指向该仓库。</li></ul>',14)])])}const b=o(d,[["render",r]]);export{q as __pageData,b as default};
